const { execSync } = require('child_process');
const fs = require('fs');

// CONFIGURACIÓN DE RUTAS (Asegúrate de que coincidan con tu PC)
const FFUF_PATH = 'C:\\Herramientas\\ffuf.exe';
const WORDLIST = 'C:\\Herramientas\\common.txt';
const TARGET = $('Loop Over Items').first().json.target
const OUTPUT_FILE = 'C:\\Herramientas\\ffuf_results.json';

try {
  // Ejecutar ffuf
  // -mc 200,301: Filtra solo resultados exitosos o redirecciones
  // -s: Modo silencioso para no ensuciar la consola
  const command = `${FFUF_PATH} -u ${TARGET}/FUZZ -w ${WORDLIST} -mc 200,301 -s -of json -o ${OUTPUT_FILE}`;

  const ffufCommand = `ffuf -u ${TARGET}/FUZZ -w ${WORDLIST} -mc 200,204,301,302,307,401,403 -s -of json -o ${OUTPUT_FILE} -t 100 -timeout 15`;

  console.log("Ejecutando ffuf...");
  execSync(ffufCommand);

  // Leer y parsear los resultados
  const rawData = fs.readFileSync(OUTPUT_FILE, 'utf8');
  const results = JSON.parse(rawData);

  return [{
    json: {
      message: "Fuzzing de directorios completado",
      ffufResults: results.results || [],
    discoveredPaths: results.results ? results.results.length : 0,
      totalFound: results.results.length,
      url: ffufCommand
    }
  }];

} catch (error) {
  return [{ json: { error: "Error en ffuf: " + error.message } }];
}

const { exec } = require('child_process');
const { promisify } = require('util');
const execAsync = promisify(exec);

const urls = $input.first().json.urlsFound || [];
const urlsWithParams = urls.filter(url => url.includes('?'));

const sqlmapResults = [];

for (const url of urlsWithParams) {
  try {
    const safeUrl = encodeURI(url);

    const command = `python "C:\\Herramientas\\sqlmap\\sqlmap.py" -u "${safeUrl}" --cookie="PHPSESSID=5b2d2ecqd054g9vgbihf5njr84; security=low" --batch --level=1 --risk=1 --output-dir=C:\\Herramientas`;

    const { stdout, stderr } = await execAsync(command, {
      timeout: 300000
    });

    if (stdout.includes('Parameter:') && stdout.includes('is vulnerable')) {
      sqlmapResults.push({
        url,
        vulnerable: true,
        details: stdout
      });
    } else {
      sqlmapResults.push({
        url,
        vulnerable: false
      });
    }

  } catch (error) {
    sqlmapResults.push({
      url,
      error: error.message
    });
  }
}

return [{
  json: {
    count: urlsWithParams.length,
    sqlmapResults,
    vulnerableUrls: sqlmapResults.filter(r => r.vulnerable).length
  }
}];

