// Mapa para gestionar vulnerabilidades únicas
const vulnerabilityMap = new Map();

// Función para clasificar severidad según CVSS
function classifySeverity(risk) {
  const riskMap = {
    'High': 'critical',
    'Medium': 'high',
    'Low': 'medium',
    'Informational': 'low'
  };
  return riskMap[risk] || 'low';
}

/**
 * Función para agregar o actualizar vulnerabilidades en el mapa
 * Evita duplicados comparando URL + Tipo
 */
function addOrUpdateVulnerability(vuln) {
  const key = `${vuln.type}`;

  if (!vulnerabilityMap.has(key)) {
    vulnerabilityMap.set(key, vuln);
  } else {
    const existing = vulnerabilityMap.get(key);
    // Si la nueva fuente es más específica (ej. SQLMap), priorizar su evidencia
    if (vuln.source === 'SQLMap' || (vuln.evidence && !existing.evidence)) {
      vulnerabilityMap.set(key, { ...existing, ...vuln });
    }
  }
}

