const ZAP_API_KEY = $input.first().json.zap_api_key
const ZAP_URL = $input.first().json.zap_url
const TARGET_URL = $input.first().json.target; 

try {
  // 1. Iniciar el Spider
  const spiderResponse = await axios.get(`${ZAP_URL}/JSON/spider/action/scan/`, {
    params: {
      apikey: ZAP_API_KEY,
      url: TARGET_URL,
